node --input-type=module <<'JS'
import{existsSync,readFileSync} from 'node:fs';
const target=process.env.TARGET_URL;
const own='.graphyard/e2e-serve-'+new URL(target).port+'.json', shared='.graphyard/e2e-serve.json';
const accepted=async file=>(await fetch(new URL('/api/scenarios',target),{headers:{Authorization:'Bearer '+JSON.parse(readFileSync(file,'utf8')).delivery.coordinatorToken}})).status===200;
if(existsSync(own)&&!await accepted(own)){console.error(own+' names another serve\'s credentials');process.exit(1);}
if(!existsSync(own)&&existsSync(shared)&&await accepted(shared)){console.error('the served head seeds the shared '+shared+', which another serve in this checkout overwrites or removes (GY-3666)');process.exit(1);}
JS
